const weekDays=['월','화','수','목','금'];
const scheduleRooms=[...new Set(programs.map(p=>p.room))];
const roomSelect=document.querySelector('#timetable-room');
for(const room of scheduleRooms){const option=document.createElement('option');option.value=room;option.textContent=room;roomSelect.append(option)}
function dayTime(p,day){if(p.title==='힐링노래교실')return day==='수'?'10:10–11:00':'11:10–12:00';return p.time}
function drawTimetable(){const selected=roomSelect.value,body=document.querySelector('#timetable-body');body.replaceChildren();for(const room of scheduleRooms.filter(room=>selected==='all'||selected===room)){const row=document.createElement('tr'),heading=document.createElement('th');heading.scope='row';heading.innerHTML=`<span>${room.split(' ')[0]}</span>${room.split(' ').slice(1).join(' ')}`;row.append(heading);for(const day of weekDays){const cell=document.createElement('td');const items=programs.filter(p=>p.room===room&&p.days.includes(day)).sort((a,b)=>dayTime(a,day).localeCompare(dayTime(b,day),'ko'));if(!items.length){const dash=document.createElement('span');dash.className='schedule-empty';dash.textContent='—';cell.append(dash)}for(const p of items){const button=document.createElement('button');button.type='button';button.className='schedule-event schedule-'+p.category;button.setAttribute('aria-label',`${day}요일 ${p.title}, ${dayTime(p,day)}, ${room} 상세 안내`);const time=document.createElement('span'),name=document.createElement('strong');time.textContent=dayTime(p,day);name.textContent=p.title;button.append(time,name);if(p.fee===0){const free=document.createElement('small');free.textContent='무료';button.append(free)}button.addEventListener('click',()=>showProgram(p));cell.append(button)}row.append(cell)}body.append(row)}document.querySelector('#timetable-status').textContent=selected==='all'?'전체 강의실 · 정규강좌 44개':selected+' · '+programs.filter(p=>p.room===selected).length+'개 강좌'}
roomSelect.addEventListener('change',drawTimetable);drawTimetable();
